pub fn fib_memo(n: u64) -> u64 {
    let mut memo: Vec<Option<u64>> = vec![None; (n + 1) as usize];
    fn helper(n: u64, memo: &mut Vec<Option<u64>>) -> u64 {
        if n < 2 { return n; }
        if let Some(v) = memo[n as usize] { return v; }
        let val = helper(n - 1, memo) + helper(n - 2, memo);
        memo[n as usize] = Some(val);
        val
    }
