```rust
use std::time::Instant;

fn fib_memo(n: u64, memo: &mut Vec<u64>) -> u64 {
    if memo[n as usize] != 0 || n <= 1 {
        return memo[n as usize];
    }
    let val = fib_memo(n - 1, memo) + fib_memo(n - 2, memo);
    memo[n as usize] = val;
    val
}

fn benchmark() -> f64 {
    let mut times = Vec::with_capacity(100_000);
    for _ in 0..100_000 {
        let mut memo = vec![0; 51];
        memo[1] = 1;
        let start = Instant::now();
        fib_memo(50, &mut memo);
        times.push(start.elapsed().as_nanos());
    }
    times.into_iter().sum::<u128>() as f64 / times.len() as f64 / 1000.0
}

fn main() {
    println!("Rust: {:.2} µs per call", benchmark());
}
