fn fibonacci_recursive_memo(n: u32, memo: &mut Vec<u64>) -> u64 {
    if n < 2 {
        return n;
    }
    if memo[n as usize] != 0 {
        return memo[n as usize];
    }
    let result = fibonacci_recursive_memo(n - 1, memo)
        + fibonacci_recursive_memo(n - 2, memo);
    memo[n as usize] = result;
    result
}

